const raw = $input.first().json;
const body = raw.body ?? raw;

const conexaoId = body.conexaoId || body.conexao_id;
const name = body.name;
const language = body.language || 'pt_BR';
const category = body.category || 'MARKETING';
const components = body.components;

if (!conexaoId) throw new Error('Campo conexaoId obrigatorio.');
if (!name || typeof name !== 'string') throw new Error('Campo name obrigatorio.');
if (!Array.isArray(components) || !components.length) {
  throw new Error('Campo components obrigatorio (array).');
}

const validCategories = ['MARKETING', 'UTILITY', 'AUTHENTICATION'];
if (!validCategories.includes(category)) {
  throw new Error('category deve ser MARKETING, UTILITY ou AUTHENTICATION.');
}

return [
  {
    json: {
      conexaoId,
      name,
      language,
      category,
      components
    }
  }
];

const entrada = $('VALIDAR ENTRADA').first().json;
const conexao = $input.first().json;

if (!conexao?.access_token || !conexao?.waba_id) {
  throw new Error('Conexao nao encontrada em SAAS_Conexoes.');
}

if (!conexao.apiOficial) {
  throw new Error('Conexao nao e API Oficial.');
}

return [
  {
    json: {
      ...entrada,
      access_token: conexao.access_token,
      waba_id: conexao.waba_id,
      phone_number_id: conexao.phone_number_id
    }
  }
];

const prev = $('MESCLAR CONEXAO').first().json;
const metaRes = $input.first().json;

if (metaRes.error) {
  throw new Error(metaRes.error.message || metaRes.error.error_user_msg || 'Falha ao criar template na Meta.');
}

return [
  {
    json: {
      conexaoId: prev.conexaoId,
      wabaId: prev.waba_id,
      nome: prev.name,
      idioma: prev.language,
      categoria: prev.category,
      componentes: prev.components,
      status: metaRes.status || 'PENDING',
      metaTemplateId: metaRes.id || null
    }
  }
];

const prev = $('VALIDAR RESPOSTA META').first().json;
const row = $input.first().json;

return [
  {
    json: {
      ok: true,
      templateId: row.id || null,
      conexaoId: prev.conexaoId,
      nome: prev.nome,
      idioma: prev.idioma,
      categoria: prev.categoria,
      status: row.status || prev.status,
      metaTemplateId: prev.metaTemplateId
    }
  }
];
